head.b:skin:
/* ============================================
   PENA EDUKASI - MODERN TEMPLATE v4.0
   Pink Sidebar + Teal Accent + Dark Mode
   ============================================ */

:root {
  --bg-body: #F8F9FA;
  --bg-card: #FFFFFF;
  --bg-sidebar: #fdf2f8;
  --bg-dark: #0f172a;
  --bg-dark-card: #1e293b;
  --bg-dark-sidebar: #1a1230;
  --text-primary: #1e293b;
  --text-secondary: #64748b;
  --text-muted: #94a3b8;
  --text-dark-primary: #f1f5f9;
  --text-dark-secondary: #94a3b8;
  --accent: #1a8a9e;
  --accent-hover: #15707f;
  --accent-light: rgba(26,138,158,0.08);
  --border: #e2e8f0;
  --border-dark: #334155;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 10px 30px rgba(0,0,0,0.1);
  --radius: 12px;
  --radius-sm: 8px;
  --radius-pill: 9999px;
  --font-sans: 'Inter',system-ui,-apple-system,sans-serif;
  --font-serif: 'Playfair Display',Georgia,serif;
  --sidebar-w: 260px;
  --sidebar-r-w: 300px;
  --tr: 0.25s ease;
}

*,*::before,*::after{box-sizing:border-box;margin:0;padding:0;}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%;}
body{font-family:var(--font-sans);background:var(--bg-body);color:var(--text-primary);line-height:1.6;-webkit-font-smoothing:antialiased;}
a{color:inherit;text-decoration:none;transition:color var(--tr);}
a:hover{color:var(--accent);}
img{max-width:100%;height:auto;display:block;}
ul,ol{list-style:none;}
button{font-family:inherit;cursor:pointer;border:none;background:none;}

/* ========== DARK MODE ========== */
body.dark-mode{background:var(--bg-dark);color:var(--text-dark-primary);}
body.dark-mode .sidebar-left{background:var(--bg-dark-sidebar);border-color:var(--border-dark);}
body.dark-mode .brand-logo{color:#5eead4;}
body.dark-mode .brand-tagline{color:var(--text-dark-secondary);}
body.dark-mode .nav-links li a{color:var(--text-dark-secondary);}
body.dark-mode .nav-links li a:hover,body.dark-mode .nav-links li a.active{background:rgba(26,138,158,0.15);color:#5eead4;}
body.dark-mode .search-input{background:rgba(255,255,255,0.05);border-color:var(--border-dark);color:var(--text-dark-primary);}
body.dark-mode .top-bar{background:var(--bg-dark-card);border-color:var(--border-dark);}
body.dark-mode .chip{background:var(--bg-dark-card);border-color:var(--border-dark);color:var(--text-dark-secondary);}
body.dark-mode .chip:hover,body.dark-mode .chip.active{background:var(--accent);border-color:var(--accent);color:#fff;}
body.dark-mode .scroll-btn{background:var(--bg-dark-card);border-color:var(--border-dark);color:var(--text-dark-secondary);}
body.dark-mode .theme-btn{background:var(--bg-dark-card);border-color:var(--border-dark);color:var(--text-dark-secondary);}
body.dark-mode .widget{background:var(--bg-dark-card);border-color:var(--border-dark);}
body.dark-mode .widget h2{color:#5eead4;border-bottom-color:var(--border-dark);}
body.dark-mode .widget .PopularPosts .item-title a{color:var(--text-dark-primary);}
body.dark-mode .widget .Label li a{background:rgba(26,138,158,0.15);color:#5eead4;}
body.dark-mode .widget .Label li a:hover{background:var(--accent);color:#fff;}
body.dark-mode .widget .BlogArchive li a{background:rgba(255,255,255,0.05);color:var(--text-dark-secondary);}
body.dark-mode .card{background:var(--bg-dark-card);border-color:var(--border-dark);}
body.dark-mode .card-title,.dark-mode .card-title a,.dark-mode .card-title h2,.dark-mode .card-title h3,.dark-mode h2.card-title,.dark-mode h3.card-title{color:var(--text-dark-primary) !important;}
body.dark-mode .card-meta{color:var(--text-dark-secondary);}
body.dark-mode .post-view .post-title{color:var(--text-dark-primary);}
body.dark-mode .post-meta{border-color:var(--border-dark);}
body.dark-mode .meta-info span{color:var(--text-dark-secondary);}
body.dark-mode .meta-info strong{color:var(--text-dark-primary);}
body.dark-mode .post-body{color:var(--text-dark-primary);}
body.dark-mode .post-body a{color:#5eead4;}
body.dark-mode .post-body blockquote{background:rgba(26,138,158,0.1);border-color:var(--accent);}
body.dark-mode .post-tags a{background:rgba(26,138,158,0.15);color:#5eead4;}
body.dark-mode .breadcrumb a{color:#5eead4;}
body.dark-mode .breadcrumb .sep{color:var(--text-dark-secondary);}
body.dark-mode .comments{border-color:var(--border-dark);}
body.dark-mode .comments .title{color:var(--text-dark-primary);}
body.dark-mode .comment{border-color:var(--border-dark);}
body.dark-mode .comment .comment-author{color:var(--text-dark-primary);}
body.dark-mode .comment .comment-body{color:var(--text-dark-primary);}
body.dark-mode .footer-main{background:var(--bg-dark-card);border-color:var(--border-dark);}
body.dark-mode .footer-main,.dark-mode .footer-main a{color:var(--text-dark-secondary);}
body.dark-mode .footer-copyright{border-color:var(--border-dark);}
body.dark-mode .sidebar-copyright{color:var(--text-dark-secondary);}
body.dark-mode .card-featured .card-title{color:#fff !important;}
body.dark-mode .card-small{background:var(--bg-dark-card);border-color:var(--border-dark);}
body.dark-mode .card-small .card-title{color:var(--text-dark-primary) !important;}
body.dark-mode .category-section{border-color:var(--border-dark);}
body.dark-mode .section-title{color:var(--text-dark-primary);}
body.dark-mode .section-link{color:#5eead4;}
body.dark-mode .scroll-top-btn{background:var(--bg-dark-card);border-color:var(--border-dark);color:var(--text-dark-secondary);}

/* ========== HAMBURGER MENU ========== */
#menu-toggle{display:none;}
.hamburger-btn{
  position:fixed;top:20px;left:20px;z-index:1100;
  width:44px;height:44px;background:var(--bg-card);border-radius:var(--radius-sm);
  display:none;flex-direction:column;align-items:center;justify-content:center;gap:5px;
  box-shadow:var(--shadow-md);cursor:pointer;border:1px solid var(--border);
}
@media(min-width:901px){.hamburger-btn{display:none !important;}}
.hamburger-btn:hover{background:var(--accent);}
.hamburger-btn:hover .bar{background:#fff;}
.bar{display:block;width:20px;height:2.5px;background:var(--text-primary);border-radius:2px;transition:all var(--tr);}
#menu-toggle:checked ~ .hamburger-btn .bar:nth-child(1){transform:translateY(7.5px) rotate(45deg);}
#menu-toggle:checked ~ .hamburger-btn .bar:nth-child(2){opacity:0;}
#menu-toggle:checked ~ .hamburger-btn .bar:nth-child(3){transform:translateY(-7.5px) rotate(-45deg);}

/* ========== SIDEBAR LEFT ========== */
.sidebar-left{
  position:fixed;top:0;left:0;width:var(--sidebar-w);height:100vh;
  background:var(--bg-sidebar);border-right:1px solid var(--border);
  z-index:1000;display:flex;flex-direction:column;
  overflow-y:auto;overflow-x:hidden;contain:strict;transition:transform 0.35s ease;
}
.sidebar-left::-webkit-scrollbar{width:3px;}
.sidebar-left::-webkit-scrollbar-thumb{background:rgba(0,0,0,0.1);border-radius:3px;}
.brand-area{padding:28px 20px 22px;border-bottom:1px solid rgba(0,0,0,0.06);text-align:center;}
.brand-logo{font-family:var(--font-serif);font-size:1.4rem;font-weight:700;color:var(--accent);letter-spacing:-0.3px;font-style:italic;display:block;}
.brand-tagline{font-size:0.76rem;color:var(--text-secondary);margin-top:4px;}
.sidebar-search{padding:15px 20px;border-bottom:1px solid rgba(0,0,0,0.06);}
.search-form{position:relative;display:flex;align-items:center;}
.search-input{
  width:100%;padding:10px 14px 10px 40px;
  border:1px solid rgba(0,0,0,0.08);border-radius:var(--radius-pill);
  font-size:0.84rem;font-family:var(--font-sans);background:rgba(255,255,255,0.75);
  color:var(--text-primary);outline:none;transition:all var(--tr);
}
.search-input:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(26,138,158,0.1);background:#fff;}
.search-input::placeholder{color:var(--text-muted);}
.search-icon{position:absolute;left:14px;top:50%;transform:translateY(-50%);width:16px;height:16px;fill:var(--text-muted);pointer-events:none;}
.nav-links{flex:1;padding:10px 0;overflow-y:auto;}
.nav-links li{margin:2px 10px;}
.nav-links li a{
  display:flex;align-items:center;gap:12px;
  padding:10px 14px;border-radius:var(--radius-sm);
  font-size:0.88rem;font-weight:500;color:var(--text-primary);transition:all var(--tr);
}
.nav-links li a:hover,.nav-links li a.active{background:var(--accent-light);color:var(--accent);box-shadow:var(--shadow-sm);}
.nav-links li a svg{width:20px;height:20px;fill:currentColor;flex-shrink:0;}
.sidebar-footer-widgets{padding:15px;border-top:1px solid rgba(0,0,0,0.06);margin-top:auto;}
.sidebar-copyright{text-align:center;font-size:0.72rem;color:var(--text-muted);padding:12px 15px;}

/* ========== MAIN WRAPPER ========== */
.main-wrapper{margin-left:var(--sidebar-w);min-height:100vh;display:flex;flex-direction:column;transition:margin 0.35s ease;}

/* ========== TOP BAR ========== */
.top-bar{position:sticky;top:0;z-index:900;background:var(--bg-body);border-bottom:1px solid var(--border);padding:0;}
.navigation-container{position:relative;display:flex;align-items:center;max-width:1400px;margin:0 auto;padding:0 15px;}
.scroll-btn{
  position:absolute;top:50%;transform:translateY(-50%);
  width:32px;height:32px;background:var(--bg-card);border:1px solid var(--border);
  border-radius:50%;display:flex;align-items:center;justify-content:center;
  font-size:1.1rem;color:var(--text-primary);box-shadow:var(--shadow-sm);z-index:10;transition:all var(--tr);
}
.scroll-btn:hover{background:var(--accent);color:#fff;border-color:var(--accent);}
.scroll-btn.left{left:5px;}
.scroll-btn.right{right:50px;}
.chip-wrapper{
  display:flex;gap:8px;padding:12px 50px;
  overflow-x:auto;scroll-behavior:smooth;
  scrollbar-width:none;-ms-overflow-style:none;
}
.chip-wrapper::-webkit-scrollbar{display:none;}
.chip{
  flex:0 0 auto;padding:8px 20px;background:var(--bg-card);
  color:var(--text-primary);font-size:0.84rem;font-weight:600;
  border-radius:var(--radius-pill);border:1px solid var(--border);
  white-space:nowrap;transition:all var(--tr);
}
.chip:hover,.chip.active{background:var(--accent);color:#fff;border-color:var(--accent);}
.topbar-actions{display:flex;gap:8px;align-items:center;flex-shrink:0;margin-left:auto;padding-left:8px;}
.theme-btn{
  width:34px;height:34px;border-radius:50%;border:1px solid var(--border);
  background:var(--bg-card);cursor:pointer;display:flex;align-items:center;
  justify-content:center;color:var(--text-secondary);transition:all var(--tr);
}
.theme-btn:hover{border-color:var(--accent);color:var(--accent);}

/* ========== CONTENT FLEX ========== */
.content-flex{display:flex;gap:20px;padding:20px;max-width:1400px;margin:0 auto;width:100%;flex:1;}
.center-grid{flex:1;min-width:0;background:transparent;padding:0;}

/* ========== POST GRID ========== */
.post-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;}
.card{
  background:var(--bg-card);border-radius:var(--radius);overflow:hidden;
  box-shadow:var(--shadow-sm);display:flex;flex-direction:column;
  transition:transform var(--tr),box-shadow var(--tr);border:1px solid var(--border);
}
.card:hover{transform:translateY(-4px);box-shadow:var(--shadow-lg);border-color:var(--accent);}
.card-thumb{width:100%;aspect-ratio:16/9;object-fit:cover;background:#f1f5f9;}
.card-thumb.no-img{display:flex;flex-direction:column;align-items:center;justify-content:center;background:#f1f5f9;}
.card-body{padding:14px;background:var(--bg-card);flex:1;display:flex;flex-direction:column;}
.card-title,.card-title h2,.card-title h3,h2.card-title,h3.card-title{
  font-size:14px;font-weight:600;line-height:1.5;color:var(--text-primary);
  margin:0 !important;padding:0 !important;border:none !important;
  text-decoration:none !important;background:none !important;box-shadow:none !important;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;
}
.card-title a,.card-title h2 a,.card-title h3 a{color:inherit;text-decoration:none !important;border:none !important;background:none !important;box-shadow:none !important;}
.card-title a:hover{color:var(--accent);}
.card-meta{display:flex;align-items:center;gap:8px;margin-top:10px;font-size:12px;color:var(--text-secondary);border:none;}

/* ========== CATEGORY SECTIONS ========== */
.category-section{margin-top:45px;padding-top:25px;border-top:1px solid var(--border);}
.section-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;}
.section-title{font-size:1.2rem;font-weight:700;color:var(--text-primary);margin:0;position:relative;padding-left:15px;}
.section-title::before{content:'';position:absolute;left:0;top:50%;transform:translateY(-50%);width:4px;height:100%;background:var(--accent);border-radius:2px;}
.section-link{font-size:13px;font-weight:600;color:var(--accent);display:flex;align-items:center;gap:4px;}
.section-link:hover{text-decoration:underline;}

/* Featured Grid: 1 big left + 4 small right */
.featured-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;}
.card-featured{position:relative;border-radius:var(--radius);overflow:hidden;background:var(--bg-card);box-shadow:var(--shadow-md);display:flex;flex-direction:column;}
.card-featured .card-thumb{width:100%;height:280px;object-fit:cover;}
.card-featured .card-overlay{position:absolute;bottom:0;left:0;right:0;padding:18px;background:linear-gradient(transparent,rgba(0,0,0,0.85));color:#fff;}
.card-featured .category-badge{display:inline-block;padding:4px 12px;background:var(--accent);color:#fff;font-size:11px;font-weight:600;border-radius:var(--radius-sm);margin-bottom:8px;text-transform:uppercase;}
.card-featured .card-title{font-size:17px;font-weight:700;color:#fff !important;margin:0 !important;line-height:1.4;-webkit-line-clamp:3;}
.card-featured .card-meta{margin-top:8px;color:rgba(255,255,255,0.8);font-size:12px;}
.card-featured:hover{transform:translateY(-3px);box-shadow:var(--shadow-lg);}
.list-cards{display:flex;flex-direction:column;gap:14px;}
.card-small{display:flex;gap:14px;padding:0;background:var(--bg-card);border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow-sm);transition:all var(--tr);border:1px solid var(--border);}
.card-small:hover{box-shadow:var(--shadow-md);border-color:var(--accent);}
.card-small .card-thumb{width:120px;min-width:120px;height:85px;object-fit:cover;border-radius:0;}
.card-small .card-body{padding:10px 14px 10px 0;display:flex;flex-direction:column;justify-content:center;flex:1;}
.card-small .card-title{font-size:13px;font-weight:600;line-height:1.4;-webkit-line-clamp:2;margin:0 !important;}
.card-small .card-meta{margin-top:6px;font-size:11px;color:var(--text-secondary);}

/* Horizontal card style for category JS */
.card-horizontal{display:flex;gap:14px;padding:0;background:var(--bg-card);border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow-sm);transition:all var(--tr);border:1px solid var(--border);margin-bottom:14px;}
.card-horizontal:hover{box-shadow:var(--shadow-md);border-color:var(--accent);}
.card-horizontal .card-thumb{width:140px;min-width:140px;height:95px;object-fit:cover;}
.card-horizontal .card-body{padding:12px 14px 12px 0;display:flex;flex-direction:column;justify-content:center;flex:1;}
.card-horizontal .card-title{font-size:14px;font-weight:600;line-height:1.4;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;color:var(--text-primary);}
.card-horizontal .card-meta{margin-top:6px;font-size:11px;color:var(--text-secondary);}

/* Category Badge */
.category-badge{display:inline-block;padding:4px 10px;background:var(--accent);color:#fff;font-size:11px;font-weight:600;border-radius:var(--radius-pill);margin-bottom:8px;}

/* Pagination */
.pagination-wrapper{margin-top:35px;text-align:center;}
.btn-pagination{
  display:inline-flex;align-items:center;gap:8px;
  padding:12px 30px;background:var(--accent);color:#fff;
  font-size:14px;font-weight:700;border-radius:var(--radius-pill);transition:all var(--tr);
}
.btn-pagination:hover{background:var(--accent-hover);color:#fff;transform:translateY(-2px);box-shadow:var(--shadow-md);}

/* ========== SIDEBAR KANAN ========== */
.sidebar-right{width:var(--sidebar-r-w);flex-shrink:0;}
.sidebar-right-inner{position:sticky;top:15px;}
.widget{background:var(--bg-card);padding:18px;border-radius:var(--radius);margin-bottom:18px;box-shadow:var(--shadow-sm);border:1px solid var(--border);}
.widget h2{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:var(--accent);margin:0 0 14px;padding-bottom:10px;border-bottom:2px solid var(--accent);}
.widget .PopularPosts ul{display:flex;flex-direction:column;gap:14px;}
.widget .PopularPosts li{display:flex;gap:12px;align-items:flex-start;}
.widget .PopularPosts .item-thumbnail{flex-shrink:0;width:75px;height:55px;border-radius:var(--radius-sm);overflow:hidden;}
.widget .PopularPosts .item-thumbnail img{width:100%;height:100%;object-fit:cover;}
.widget .PopularPosts .item-title{flex:1;}
.widget .PopularPosts .item-title a{font-size:13px;font-weight:600;line-height:1.4;color:var(--text-primary);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;}
.widget .PopularPosts .item-title a:hover{color:var(--accent);}
.widget .Label ul{display:flex;flex-wrap:wrap;gap:8px;}
.widget .Label li a{display:inline-block;padding:5px 14px;background:#f1f5f9;color:var(--text-primary);font-size:12px;font-weight:500;border-radius:var(--radius-pill);transition:all var(--tr);}
.widget .Label li a:hover{background:var(--accent);color:#fff;}
.widget .BlogArchive ul{display:flex;flex-direction:column;gap:6px;}
.widget .BlogArchive li a{display:flex;justify-content:space-between;padding:7px 12px;background:#f1f5f9;border-radius:var(--radius-sm);font-size:13px;color:var(--text-primary);transition:all var(--tr);}
.widget .BlogArchive li a:hover{background:var(--accent);color:#fff;}

/* ========== POST VIEW / SINGLE ========== */
.post-view{background:transparent;max-width:100%;}
.breadcrumb{display:flex;align-items:center;flex-wrap:wrap;gap:5px;font-size:14px;color:var(--text-secondary);margin-bottom:18px;}
.breadcrumb a{color:var(--accent);font-weight:500;}
.breadcrumb a:hover{text-decoration:underline;}
.breadcrumb .sep{color:var(--text-muted);}
.post-view .post-title{font-size:30px;font-weight:800;line-height:1.3;color:var(--text-primary);margin-bottom:18px;}
.post-meta{display:flex;align-items:center;gap:14px;margin-bottom:22px;padding-bottom:18px;border-bottom:1px solid var(--border);}
.author-photo-wrapper{width:46px;height:46px;border-radius:50%;background:#f1f5f9;border:2px solid var(--border);display:flex;align-items:center;justify-content:center;flex-shrink:0;overflow:hidden;}
.author-photo-wrapper img{width:100%;height:100%;object-fit:cover;}
.author-thumb-svg{width:26px;height:26px;fill:var(--text-muted);}
.meta-info{display:flex;flex-direction:column;gap:2px;}
.meta-info span{font-size:13px;color:var(--text-secondary);line-height:1.4;}
.meta-info strong{color:var(--text-primary);font-weight:600;}
.post-body{font-size:17px;line-height:1.85;color:var(--text-primary);}
.post-body h2,.post-body h3,.post-body h4{margin-top:30px;margin-bottom:14px;font-weight:700;line-height:1.3;color:var(--text-primary);}
.post-body h2{font-size:24px;}
.post-body h3{font-size:20px;}
.post-body h4{font-size:17px;}
.post-body p{margin-bottom:18px;}
.post-body img{border-radius:var(--radius);margin:22px 0;}
.post-body ul,.post-body ol{margin:18px 0;padding-left:24px;}
.post-body ul{list-style:disc;}
.post-body ol{list-style:decimal;}
.post-body li{margin-bottom:8px;}
.post-body a{color:var(--accent);font-weight:500;}
.post-body a:hover{text-decoration:underline;}
.post-body blockquote{margin:22px 0;padding:18px 22px;background:#f1f5f9;border-left:4px solid var(--accent);border-radius:0 var(--radius-sm) var(--radius-sm) 0;font-style:italic;}
.post-body pre,.post-body code{font-family:'SF Mono','Fira Code',Consolas,monospace;background:#f1f5f9;border-radius:var(--radius-sm);}
.post-body code{padding:2px 6px;font-size:0.9em;}
.post-body pre{padding:18px;overflow-x:auto;}
.post-body pre code{padding:0;background:none;}
.post-tags{margin-top:25px;padding-top:18px;border-top:1px solid var(--border);}
.post-tags a{display:inline-block;padding:5px 14px;background:#f1f5f9;color:var(--text-primary);font-size:12px;font-weight:500;border-radius:var(--radius-pill);transition:all var(--tr);margin:3px;}
.post-tags a:hover{background:var(--accent);color:#fff;}

/* ========== COMMENTS ========== */
.comments{margin-top:40px;padding-top:25px;border-top:1px solid var(--border);}
.comments .title{font-size:18px;font-weight:700;color:var(--text-primary);margin-bottom:20px;}
.comment{display:flex;gap:14px;margin-bottom:22px;padding-bottom:22px;border-bottom:1px solid #f1f5f9;}
.comment .avatar-image-container{flex-shrink:0;}
.comment .avatar-image-container img{width:42px;height:42px;border-radius:50%;}
.comment .comment-block{flex:1;}
.comment .comment-author{font-weight:600;color:var(--text-primary);margin-bottom:6px;font-size:14px;}
.comment .comment-body{font-size:14px;line-height:1.6;color:var(--text-primary);}
.comment .comment-timestamp{font-size:12px;color:var(--text-secondary);margin-top:8px;}

/* ========== FOOTER ========== */
.footer-main{background:var(--bg-card);border-top:1px solid var(--border);padding:40px 20px;text-align:center;margin-top:auto;}
.footer-copyright{margin-top:20px;padding-top:15px;border-top:1px solid var(--border);font-size:12px;color:var(--text-secondary);}

/* ========== SCROLL TO TOP ========== */
.scroll-top-btn{
  position:fixed;bottom:25px;right:25px;width:42px;height:42px;
  background:var(--bg-card);border:1px solid var(--border);border-radius:50%;
  display:none;align-items:center;justify-content:center;
  box-shadow:var(--shadow-md);cursor:pointer;z-index:999;
  color:var(--accent);font-size:1.1rem;transition:all var(--tr);
}
.scroll-top-btn:hover{background:var(--accent);color:#fff;border-color:var(--accent);transform:translateY(-3px);}
.scroll-top-btn.show{display:flex;}

/* ========== RESPONSIVE ========== */
@media(max-width:1200px){
  .post-grid{grid-template-columns:repeat(2,1fr);}
  .sidebar-right{display:none;}
  .content-flex{padding:15px;}
}
@media(max-width:900px){
  :root{--sidebar-w:280px;}
  .hamburger-btn{display:flex;}
  .sidebar-left{transform:translateX(-100%);}
  #menu-toggle:checked ~ .sidebar-left{transform:translateX(0);}
  .sidebar-overlay{position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:999;opacity:0;visibility:hidden;transition:all var(--tr);}
  #menu-toggle:checked ~ .sidebar-overlay{opacity:1;visibility:visible;}
  .main-wrapper{margin-left:0;}
  .top-bar{padding-top:60px;}
  .chip-wrapper{padding:10px 40px;}
  .chip{padding:7px 16px;font-size:13px;}
  .featured-grid{grid-template-columns:1fr;}
  .card-featured .card-thumb{height:200px;}
  .list-cards{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;}
  .card-small{flex-direction:column;}
  .card-small .card-thumb{width:100%;height:100px;}
  .card-small .card-body{padding:10px;}
}
@media(max-width:600px){
  .post-grid{grid-template-columns:1fr;gap:14px;}
  .content-flex{padding:12px;}
  .post-view .post-title{font-size:22px;}
  .post-body{font-size:15px;line-height:1.75;}
  .list-cards{grid-template-columns:1fr;}
  .card-horizontal{flex-direction:column;}
  .card-horizontal .card-thumb{width:100%;height:140px;min-width:auto;}
  .card-horizontal .card-body{padding:12px;}
  .btn-pagination{width:100%;justify-content:center;}
}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:0.01ms !important;transition-duration:0.01ms !important;scroll-behavior:auto !important;}}
@media print{.sidebar-left,.sidebar-right,.top-bar,.hamburger-btn,.footer-main,.scroll-top-btn{display:none !important;}.main-wrapper{margin:0 !important;}}

.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0;}

body.script:
//
function scrollChips(d){var c=document.getElementById('chipWrapper');if(c)c.scrollLeft+=d*200;}

document.addEventListener('DOMContentLoaded',function(){
  var path=window.location.pathname;
  var search=window.location.search;
  var full=path+search;

  document.querySelectorAll('.nav-links a').forEach(function(l){
    if(l.getAttribute('href')===path||l.getAttribute('href')===full){l.classList.add('active');l.setAttribute('aria-current','page');}
  });

  document.querySelectorAll('.chip').forEach(function(c){
    c.classList.remove('active');
    if(c.getAttribute('href')===path||c.getAttribute('href')===full)c.classList.add('active');
  });

  document.querySelectorAll('img').forEach(function(img){
    img.addEventListener('error',function(){this.style.display='none';});
    if(!img.getAttribute('alt'))img.setAttribute('alt','Pena Edukasi');
  });

  var mt=document.getElementById('menu-toggle');
  var ov=document.querySelector('.sidebar-overlay');
  if(ov&&mt){ov.addEventListener('click',function(){mt.checked=false;});}

  window.addEventListener('scroll',function(){
    var btn=document.getElementById('scrollTopBtn');
    if(btn){if(window.scrollY>400)btn.classList.add('show');else btn.classList.remove('show');}
  });
});

document.addEventListener('touchstart',function(){},{passive:true});
document.addEventListener('touchmove',function(){},{passive:true});
document.addEventListener('wheel',function(){},{passive:true});

// Dark Mode
function toggleDarkMode(){
  document.body.classList.toggle('dark-mode');
  localStorage.setItem('darkMode',document.body.classList.contains('dark-mode')?'1':'0');
}
if(localStorage.getItem('darkMode')==='1')document.body.classList.add('dark-mode');

// Load Category Posts
function loadCategoryPosts(label,containerId,maxPosts){
  var container=document.getElementById(containerId);
  if(!container)return;
  var feedUrl='/feeds/posts/default/-/'+encodeURIComponent(label)+'?alt=json&max-results='+maxPosts;
  fetch(feedUrl)
    .then(function(r){return r.json();})
    .then(function(data){
      if(!data.feed.entry){container.innerHTML='<p style="color:var(--text-secondary);font-size:14px;">Belum ada artikel.</p>';return;}
      var html='';
      data.feed.entry.forEach(function(entry){
        var title=entry.title.$t;
        var link='';
        for(var i=0;i<entry.link.length;i++){if(entry.link[i].rel=='alternate'){link=entry.link[i].href;break;}}
        var thumb='';
        if(entry.media$thumbnail){thumb=entry.media$thumbnail.url.replace('/s72-c/','/w280-h160-c/');}
        else if(entry.content&&entry.content.$t){var m=entry.content.$t.match(/<img[^>]+src=["']([^"']+)["']/i);if(m)thumb=m[1];}
        var date='';
        if(entry.published&&entry.published.$t){var d=new Date(entry.published.$t);var months=['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];date=d.getDate()+' '+months[d.getMonth()]+' '+d.getFullYear();}
        html+='<a class="card-horizontal" href="'+link+'">';
        if(thumb){html+='<img alt="'+title.replace(/"/g,'&quot;')+'" class="card-thumb" loading="lazy" src="'+thumb+'"/>';}
        else{html+='<div class="card-thumb" style="background:#f1f5f9;display:flex;align-items:center;justify-content:center;width:140px;min-width:140px;height:95px;"><svg style="width:30px;height:30px;fill:#bdc3c7;" viewBox="0 0 24 24"><path d="M21 19V5c0-1.1-.9-2-2-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2zM8.5 13.5l2.5 3.01L14.5 12l4.5 6H5l3.5-4.5z"/></svg></div>';}
        html+='<div class="card-body"><h3 class="card-title">'+title+'</h3><div class="card-meta"><span>'+date+'</span></div></div></a>';
      });
      container.innerHTML=html;
    })
    .catch(function(){container.innerHTML='<p style="color:var(--text-secondary);font-size:14px;">Gagal memuat artikel.</p>';});
}

if(document.getElementById('cat-pendidikan'))loadCategoryPosts('Pendidikan','cat-pendidikan',4);
if(document.getElementById('cat-tutorial'))loadCategoryPosts('Tutorial','cat-tutorial',4);
if(document.getElementById('cat-materi'))loadCategoryPosts('Materi','cat-materi',4);
//
